package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMaiDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_q_lut_najjini_ahli" to DuaText("लूत (ए. एस.) क दुआ-हमर परिवार बचाउ।", "हे हमर प्रभु, हमरा आ हमर परिवार केँ ओ सभ काज सँ बचा लिअ।", "अपन परिवार केँ दुष्ट वातावरण सँ बचाउ।", "परिवार केँ बुराई सँ बचाउ।"),
        "dua_q_sulaiman_awzini" to DuaText("सुलेमान (ए. एस.) के दुआ आभार के लिए", "हे हमर प्रभु, अहाँ हमरा आ हमर माता-पिता पर जे अनुग्रह कयलहुँ, ताहि लेल आभार व्यक्त करू आ नीक काज करू जे अहाँ प्रसन्न छी आ अपन दयालुता सँ हमरा अपन धर्मी सेवक सभक बीच प्रवेश दिलाउ।", "आशीर्वादक लेल आभारी होयबाक क्षमताक लेल।", "सुलेमान (ए. एस.) के कृतज्ञताक दुआ।"),
        "dua_q_musa_zalamtu" to DuaText("मूसा (अ. स.) क दुआ-हम अपन संग गलत कयलहुँ।", "हे हमर प्रभु, हम अपन ऊपर अन्याय कयलहुँ, तेँ हमरा क्षमा कऽ दियौक।", "गलतीक बाद तत्काल पश्चाताप।", "अल्लाह मूसाक (अ. स.) क्षमा कऽ देलनि।"),
        "dua_q_musa_najjini" to DuaText("मूसा (अ. स.) क दुआ-हमरा उत्पीड़कसँ बचा लिअ।", "हे हमर प्रभु, हमरा अधर्मी लोक सभ सँ बचा लिअ।", "जखन उत्पीड़कसँ डरैत छी।", "मिस्र छोड़ैत समय मूसा (ए. एस.) के दुआ।"),
        "dua_q_lut_unsurni" to DuaText("लूत (ए. एस.) क दुआ-भ्रष्टलोकनिक विरुद्ध सहायता", "हे हमर प्रभु, भ्रष्ट लोक सभक विरुद्ध हमरा सहायता करू।", "भ्रष्टाचार फैला रहल लोकक विरुद्ध सहायता लेल।", "सत्य पर अटल रहबाक लेल दुआ।"),
        "dua_q_hab_li_salihin" to DuaText("एक धर्मी बालक लेल इब्राहिम (ए. एस.) के दुआ", "हे हमर प्रभु, हमरा धर्मपरायण सभक मध्यसँ एकटा सन्तान प्रदान करू।", "धर्मी बच्चासभसँ माँगैत।", "एहि माध्यम सँ दुआ इस्माइल (ए. एस.) प्रदान कयल गेल।"),
        "dua_q_wasita_kulla_shay" to DuaText("सिंहासन धारण करैवला स्वर्गदूतसभक दुआ", "हे हमर प्रभु, अहाँ सभ किछु दया आ ज्ञान सँ घेरैत छी, तेँ तकरा सभ केँ क्षमा करू जे पश्चाताप करैत अछि आ अहाँक मार्ग पर चलैत अछि आ ओकरा सभ केँ नरकक दण्ड सँ बचबैत अछि।", "सिंहासन धारण करैवला स्वर्गदूत विश्वासीक लेल ई दुआ बनबैत छथि।", "स्वर्गदूतसभक दुआमे सम्मिलित होयबाक उद्देश्यसँ पाठ कयल गेल।"),
        "dua_q_ikhwanina" to DuaText("हमर भाय सभक लेल जे हमरा सँ पहिने छलाह।", "ऐ हमर प्रभु, हमरा सभ केँ आ हमर भाय सभ केँ जे विश्वास मे हमरा सँ पहिने आयल छलाह क्षमा करी आ जे विश्वास कयने छलाह तकरा सभ सँ हमरा सभक मन मे कोनो राग नहि करू। हमर प्रभु, अहाँ बड्ड दयालु आ दयावान छी।", "पहिने आयल विश्वासी सभक लेल आ शुद्ध हृदयक लेल दुआ।", "कुलीन साथी (आर. ए.) आ पहिनेक विश्वासी सभक लेल एक दुआ।"),
        "dua_q_alayka_tawakkalna" to DuaText("हम अहाँ पर भरोसा करैत छी (इब्राहिम)", "ऐ हमर प्रभु, हम सभ अहाँ पर भरोसा करैत छी, हम सभ अहाँ दिस फिरैत छी आ अहाँ दिस फेरैत छी। हमर प्रभु, हमरा सभ केँ इनकार करयवालोकनि लेल परीक्षा नहि बनाउ आ हमरा सभ केँ क्षमा कऽ दियौक। हमर प्रभु, अहाँ सभ अवश्य सर्वशक्तिमान, तत्वदर्शी छी।", "इब्राहिम (अ. स.) आ हुनकर साथी सभक दुआ।", "अल्लाह पर निर्भर रहबाक आ हुनका दिस मुड़बाक दुआ।"),
        "dua_q_atmim_nurana" to DuaText("हमर प्रकाशकेँ पूर्ण करू।", "हे हमर प्रभु, हमरा सभक लेल इजोत पूरा करू आ हमरा सभ केँ क्षमा करू। निश्चय ही अहाँ सभ सब बात पर अधिकार करैत छी।", "पुनरुत्थानक दिन विश्वासी सभक दुआ।", "सीराट पर रोशनी के माँगैत।"),
        "dua_q_asiya_baytan" to DuaText("आसियाक दुआ-जन्नतमे एकटा घर", "हे हमर प्रभु, हमरा लग स्वर्गमे एकटा घर बनाउ, फेरौन आ ओकर काज सँ हमरा बचाउ आ दुष्ट लोक सभ सँ हमरा बचाउ।", "आसियाक दुआ, फ़िरौनक पत्नी।", "अल्लाह हुनका विश्वासी सभक लेल एकटा उदाहरण बनौलनि।"),
        "dua_adhan_response" to DuaText("अधानकेँ उत्तर दियौक", "अल्लाह के अलावा कोनो शक्ति आ शक्ति नहि अछि।", "मुअज्जिन जे कहैत छथि, ओकरा दोहराउ;'हय्या'अलास-सलाह'आ'हय्या'अलाल-फलाह'मे ई कहैत छी।", "जे हृदयसँ उत्तर देत, से स्वर्गमे प्रवेश करत।"),
        "dua_adhan_shahadah" to DuaText("मुअज्जिनक शहादाक बाद", "हम सेहो गवाही दैत छी जे अल्लाहके छोड़ि कोनो लोकक पूजा करबाक अधिकार नहि अछि, केवल अल्लाह, बिना साझीदार, आ मुहम्मद सल्लल्लाहु अलैहि वसल्लम हुनकर सेवक आ रसूल छथि। हम अल्लाहसँ प्रभु, मुहम्मद सल्लल्लाहु अलैहि वसल्लम सँ रसूल आ इस्लाम सँ धर्मक रूपमे प्रसन्न छी।", "मुएज़्ज़िनक विश्वासक गवाही सुनबा पर।", "हुनकर पाप क्षमा भऽ जायत।"),
        "dua_istiftah_baid" to DuaText("दुआ खोलनाः हमरा पापसँ दूर राखू।", "ऐ अल्लाह, हमरा हमर पाप सँ दूर करू, जेना अहाँ पूरब केँ पश्चिम सँ दूर कऽ देलहुँ। ऐ अल्लाह, हमरा पाप सँ शुद्ध करू, जेना एकटा सफेद वस्त्र मे मैल छल। ऐ अल्लाह, हमर पापसभ पानि, बर्फ आ ओसल सँ धोउ।", "उद्घाटन तकबीरक बाद (सनाक स्थान पर सेहो कहल जा सकैत अछि)।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम ताकबीर आ पाठक बीच ई पाठ कयलनि।"),
        "dua_hamdan_kathiran" to DuaText("रुकुक बाद भरपूर प्रशंसा", "हमर प्रभु, अहाँक प्रशंसा प्रचुर, शुद्ध आ धन्य अछि।", "रुकूसँ उठलाक बाद'रब्बाना लकल-हमद'क संग।", "तीससँ बेसी स्वर्गदूत एकरा रिकॉर्ड करय वला पहिल व्यक्ति बनबाक लेल दौड़मे छलाह।"),
        "dua_subbuhun_quddus" to DuaText("सुब्बूहुन कुद्दुस (रुकू आ सुजूद)", "(अल्लाह) सबसँ महिमावान, सबसँ पवित्र, स्वर्गदूत आ आत्माक (जिब्रिल) प्रभु छथि।", "रुकू आ सुजूद मे।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम रुकू आ सुजूद मे एकर पाठ कयलनि।"),
        "dua_sujood_dhanbi_kullah" to DuaText("सुजूदः हमर सभ पाप क्षमा करू।", "ओ अल्लाह, हमर सभ पाप क्षमा करू-छोट आ पैघ, पहिल आ अन्तिम, खुला आ गुप्त।", "सुजूद मे।", "प्रोस्ट्रेशन एकटा एहन स्थान अछि जतय दुआक उत्तर देल जाइत अछि।"),
        "dua_sujood_ridaka" to DuaText("अपन खुशीमे शरण", "ऐ अल्लाह, हम अहाँक क्रोध सँ अहाँक प्रसन्नतामे शरण चाहैत छी, अहाँक दंड सँ क्षमा करैत छी, आ हम अहाँ सँ शरण लैत छी। हम पूर्ण रूपसँ अहाँक प्रशंसा नहि कऽ सकैत छी; अहाँ जेना अपन प्रशंसा कयने छी तहिना अहाँ सेहो छी।", "सुजूद मे आयशा (रा.) पैगम्बर सल्लल्लाहु अलैहि वसल्लम के ई कहैत सुनलनि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के एक सुजूद दुआ।"),
        "dua_tashahhud" to DuaText("ताशाहहुद (अत-ताहियत)", "सब मौखिक, शारीरिक आ आर्थिक पूजा अल्लाह के लेल अछि। हे पैगम्बर, अहाँ पर शान्ति हो आ अल्लाह के दया आ हुनकर आशीर्वाद हो। हमरा पर आ अल्लाह के नेक सेवकों पर शान्ति हो। हम गवाही दैत छी जे अल्लाह के अलावा ककरो पूजा करबाक अधिकार नहि अछि, आ हम गवाही दैत छी जे मुहम्मद सल्लल्लाहु अलैहि वसल्लम हुनकर सेवक आ रसूल छथि।", "प्रत्येक बैठकमे-अब्दुल्ला इब्न मसूद (र.) (हनाफी प्रथा) द्वारा वर्णित।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एकरा कुरानक सूराक रूपमे सिखौलनि।"),
        "dua_sajdah_tilawah" to DuaText("पाठक सजदा", "हमर मुख तकरा सभ केँ प्रणाम कयलक जे एकरा बनाए आ अपन शक्ति आ शक्ति सँ एकर श्रवण आ दृष्टि उत्पन्न कयलक।", "पठनक प्रणाममे।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम राति मे सजदा करैत ई कहलनि।"),
        "dua_after_witr" to DuaText("विद्रक बाद", "महिमावान राजा, परम पवित्र।", "तीन बेर विदरक नमाज़क बाद, तेसर बेर आवाज उठबैत।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम ई बात विदरक बाद कहलनि।"),
        "dua_tahajjud_nur" to DuaText("तहज्जुदक उद्घाटन प्रार्थना", "ऐ अल्लाह, प्रशंसा अहाँक अछि; अहाँ आकाश, पृथ्वी आ ओकर भीतरक सभ किछुक पालनकर्ता छी। प्रशंसा अहाँक अछि। अहाँ आकाश, पृथ्वी आ ओकर भीतरक सभ किछुक ज्योति छी। प्रशंसा अहाँक अछि। अहाँ सत्य छी, अहाँक वचन सत्य अछि, अहाँक भेंट सत्य अछि, अहाँक वचन सत्य अछि, स्वर्ग सत्य अछि, नरक सत्य अछि, पैगम्बर सत्य अछि, मुहम्मद सल्लल्लाहु अलैहि वसल्लम सत्य अछि आ घड़ी सत्य अछि।", "जखन राति प्रार्थना (तहज्जुद) (दुआक उद्घाटन भाग) शुरू होइत अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम तहज्जुदक लेल उठबा पर ई पाठ कयलनि (पूरा दुआ अल-बुखारीमे अछि)।"),
        "dua_rabba_jibrail" to DuaText("विवादित मामिलामे हमर मार्गदर्शन करू।", "ऐ अल्लाह, जिब्रिल, मीकाईल आ इसराफिलक रब, आकाश आ पृथ्वीक निर्माता, अदृश्य आ दृष्टि-सम्बन्धी जानकार! अहाँ अपन दास सभक बीच ओहि बातक न्याय करब जे ओ सभ आपसमे मतभेद करैत छलाह। अपन अनुमति सँ हमरा सत्यक मार्ग देखाउ जे बात पर मतभेद अछि। निश्चय ही अहाँ जकरा चाहियो ओकरा सीधा मार्ग दिस लऽ जाइत छी।", "तहज्जुदक प्रारम्भमे-असहमतिक बीच सत्यक मार्गदर्शन लेल।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम एहि दुआक सङ्ग अपन राति प्रार्थना शुरू कयलनि।"),
        "dua_going_to_mosque_nur" to DuaText("मस्जिद (प्रकाशक दुआ) जा रहल छी।", "हे अल्लाह, हमर हृदय मे इजोत, हमर आँखि मे इजोत, हमर कान मे इजोत, हमर दाहिना मे इजोत, हमर बाएँ मे इजोत, हमरा ऊपर इजोत, हमर नीचा मे इजोत, हमर सामने इजोत, हमर पाछाँ इजोत आ हमर लेल इजोत बनाउ।", "फजर लेल मस्जिद जाय पर।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम नमाज़ पढ़बाक लेल बाहर जाइत काल ई पाठ कयलनि।"),
        "dua_waswasa_salah" to DuaText("वास्वासा सलाहक समय (खिन्जाब)", "हम शापित शयतान सँ अल्लाह मे शरण चाहैत छी।", "प्रार्थनाक क्रममे जखन शैतानक फुसफुस अबैत अछि तँ शरण लिअ आ तीन बेर बाम दिस हल्का-हल्का थूकू।", "उथमान इब्न अबिल -'अस (रा.) ई कयलनि आ फुसफुस दूर भऽ गेल।"),
        "dua_alimal_ghayb" to DuaText("अदृश्य के जानकार", "ऐ अल्लाह, अदृश्य आ दृश्यक जानकार, आकाश आ पृथ्वीक निर्माता, प्रभु आ सभ वस्तुक शासक! हम गवाही दैत छी जे अहाँक अतिरिक्त कोनो देवता नहि अछि। हम अहाँ मे अपन दुष्टता, शयतानक दुष्टता आ ओकर (पुकारबाक) शिर्क सँ शरण चाहैत छी।", "भोर, साँझ आ सोबासँ पहिने-पैगम्बर सल्लल्लाहु अलैहि वसल्लम आबू बकर (र.) केँ ई सिखौलनि।", "स्वयं आ शैतानक दुष्टतासँ सुरक्षा।"),
        "dua_fitratil_islam" to DuaText("इस्लामक फित्राह पर", "हम सभ इस्लामक फित्राक भोरमे, अपन पैगम्बर मुहम्मद सल्लल्लाहु अलैहि वसल्लम के धर्म पर, आ अपन पिता इब्राहिम (अ. स.) के मार्ग पर, जे सीधा आ मुसलमान छलाह, आ मुशरिक नहि छलाह, ईमानदारीक वचन पर प्रवेश कयलहुँ।", "भोरमे।", "हर सुबह अपन विश्वासकेँ नव रूप देब।"),
        "dua_amsayna_fitrah" to DuaText("इस्लामक फित्राक साँझ", "हम सभ इस्लामक फित्राक साँझमे, अपन पैगम्बर मुहम्मद सल्लल्लाहु अलैहि वसल्लम के धर्म पर, अपन पिता इब्राहिम (अ. स.) के मार्ग पर, जे सीधा आ मुसलमान छलाह, आ मुशरिक नहि छलाह, ईमानदारीक वचन पर प्रवेश कयलहुँ।", "साँझमे।", "हर साँझ अपन विश्वासकेँ नव रूप देब।"),
        "dua_tahleel_10_fajr" to DuaText("फजर आ माघरीबक बाद दस तहलील", "ककरो पूजा करबाक अधिकार नहि अछि सिवाय अल्लाह के, मात्र, बिना साझीदारक। शासन हुनकर अछि आ प्रशंसा हुनकर अछि; ओ जीवन दैत छथि आ मृत्यु दैत छथि, आ ओ सब चीज पर शक्ति रखैत छथि।", "फजर (आ माघरीब) क दस बेर बाद, अपन बैठक या बोलनेसँ हटबासँ पहिने।", "दस नीक काज, दस पाप मिटायल गेल, दस पद बढ़ाओल गेल आ पूरा दिन शैतानसँ सुरक्षा।"),
        "dua_la_hawla_kanz" to DuaText("जन्नाक खजाना", "अल्लाह के अलावा कोनो शक्ति आ शक्ति नहि अछि।", "प्रायः, हर समय।", "ई स्वर्गक खजाना मे सँ एक अछि।"),
        "dua_four_beloved_words" to DuaText("चारि सबसँ प्रिय शब्दसभ", "महिमावान अल्लाह छथि, समस्त प्रशंसा अल्लाह के लेल अछि, अल्लाह के अतिरिक्त ककरो पूजा करबाक अधिकार नहि अछि, आ अल्लाह सबसँ महान छथि।", "ई शब्द अल्लाह केँ सबसँ प्रिय अछि।", "ई सब पैगम्बर सल्लल्लाहु अलैहि वसल्लम केँ सूर्यक सब किछु पर उगयवला सँ बेसी प्रिय अछि।"),
        "dua_two_light_words" to DuaText("दूटा शब्द जीभ पर प्रकाश करैत अछि", "महिमावान अल्लाह छथि आ समस्त प्रशंसा हुनकर अछि; महिमावान अल्लाह छथि, जे महान छथि।", "जिब्रो पर हल्का, स्केल पर भारी।", "परम करुणामयसँ प्रेम करैत छी, जिब्रो पर हल्का आ स्केल पर भारी। (बुखारीक अन्तिम हदीस)"),
        "dua_ya_dhal_jalal" to DuaText("या धल-जलाली वाल-इकराम", "ओ महामहिम आ सम्मानक स्वामी!", "पैगम्बर सल्लल्लाहु अलैहि वसल्लमक निर्देशक अनुसार एकरा पकड़ू।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहलनि जे'या धल-जलाली वाल-इकराम'केँ पकड़ू।"),
        "dua_sleep_wadatu_janbi" to DuaText("हम अहाँक नाम पर लेटैत छी।", "4 \"हे हमर प्रभु, हम अहाँक नाम सँ अपना पक्ष राखैत छी आ अहाँक नाम सँ उठैत छी। जँ अहाँ हमर प्राण लैत छी तँ ओहि पर दया करू आ जँ अहाँ ओकरा छोड़ैत छी तँ ओकरा सुरक्षित राखू जेना अहाँ अपन धर्मी सेवकेंक रक्षा करैत छी।", "बिस्तर पर धूल फेरबाक बाद लेट जाउ।", "सोबासँ पहिने अपन प्राण अल्लाहकेँ सौंपब।"),
        "dua_sleep_khalaqta_nafsi" to DuaText("अहाँ हमर आत्माक निर्माण कयलहुँ।", "ऐ अल्लाह, अहाँ हमर प्राणक निर्माण कयलहुँ आ अहाँ ओकरा लऽ लेलहुँ। एकर मृत्यु आ जीवन अहाँक अछि। जँ अहाँ एकरा जीवित राखब तँ एकर रक्षा करू, आ जँ अहाँ ओकरा मरिबैत छी तँ एकरा क्षमा करू। हे अल्लाह, हम अहाँक कल्याणक प्रार्थना करैत छी।", "सोबासँ पहिने-इब्न उमर (र.) द्वारा वर्णित अछि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सूनाइ पर ई कहबाक निर्देश देलनि।"),
        "dua_sleep_atamana" to DuaText("सोबासँ पहिने आभार व्यक्त करू।", "प्रशंसा अछि ओ अल्लाह के जे हमरा सभ केँ खुआओलनि, पीऔलनि, पर्याप्त पओलनि आ आश्रय देलनि। कतेक एहन छथि जे लग एहन कोनो नहि अछि जे हुनका सभ केँ पर्याप्त भोजन दऽ सकय आ आश्रय नहि दऽ सकय।", "सोते समय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सोबैत काल ई कहलनि।"),
        "dua_sleep_rabbas_samawat" to DuaText("स्वर्गक स्वामी-हमर ऋण चुकाइ दियौक।", "ऐ आकाश, पृथ्वी आ शक्तिशाली सिंहासनक स्वामी, हमर प्रभु, सब वस्तुक स्वामी, बीज आ खर्जूरक विभाजक, तोराक, इंजिल आ फुरकानक प्रकटक, हम अहाँ मे ओहि सब दुष्टतासँ शरण चाहैत छी जकरा अहाँ पकड़ैत छी। ऐ अल्लाह, अहाँ पहिल छी, अहाँ सँ पहिने किछु नहि अछि; अहाँ अन्तिम छी, अहाँक बाद किछु नहि अछि; अहाँ प्रकट छी, अहाँ सँ किछु नहि अछि, अहाँ सँ किछु नहि अछि। अहाँ लुके हुए छी, अहाँ सँ किछु नहि अछि। हमरा सभक लेल हमर ऋण चुकाइ दियौक आ हमरा सभ केँ गरीबी सँ मुक्त करू।", "सोबासँ पहिने दाहिनी कात लेटब-फातिमा (रा.) केँ सिखायल गेल।", "ऋण आ कष्टसँ राहत लेल दुआ।"),
        "dua_sleep_fear" to DuaText("नींदमे डर या बेचैनी", "हम हुनकर क्रोध आ हुनकर सजा सँ, हुनकर सेवक सभक दुष्टता सँ, दुष्ट दुष्टात्मा सभक फुसफुस सँ आ हमरा लग आबिबा सँ अल्लाह के पूर्ण वचन मे शरण चाहैत छी।", "जखन नींदमे भय वा बेचैनी महसूस होइत अछि।", "एना कयबा सँ ओकरा कोनो हानि नहि होयत।"),
        "dua_waking_afani" to DuaText("जागनाः ओ हमर आत्माक पुनर्स्थापना कयलनि।", "हमर शरीरकेँ कल्याण प्रदान कय, हमर प्राण हमरा लग पठौलनि आ हमरा हुनका स्मरण करबाक अनुमति देलनि, ई प्रशंसा ओ अल्लाहक अछि।", "जागैत।", "एकटा नव भोरक लेल आभार।"),
        "dua_allahu_rabbi" to DuaText("अल्लाह, अल्लाह हमर प्रभु छथि।", "ऐ अल्लाह, ऐ अल्लाह हमर प्रभु छथि; हम हुनका संग कोनो बातक साझी नहि बनबैत छी।", "दुख या दुख मे-पैगम्बर सल्लल्लाहु अलैहि वसल्लम एकरा अस्मा बिन्त उमैस (रा.) केँ सिखौलनि।", "संकटक समय तौहिदकेँ पकड़ैत रहू।"),
    )
}
